design.css:
/* Floating native-style windows. Plasma is optional. */
:scope {
  --tigrana-panel-gap: 18px;
  --tigrana-workspace-inset: 18px;
  --tigrana-panel-radius: 16px;
  --tigrana-panel-shadow: 0 12px 32px #00000024, 0 2px 5px #00000012;
  --tigrana-workspace-background: linear-gradient(135deg, color-mix(in srgb, var(--tigrana-accent) 20%, var(--surface-muted)), var(--surface-soft) 55%, color-mix(in srgb, var(--tigrana-accent) 10%, var(--surface-muted)));
}
.app-titlebar { background: var(--surface-soft); border-bottom: 0; }
.note-tab { border-radius: 9px; margin: 4px 3px; background: transparent; }
.app-titlebar .note-tab.is-active { background: var(--surface-strong); color: var(--tigrana-text); box-shadow: 0 1px 5px #00000020; border: 1px solid var(--tigrana-border); }
.folder-pane, .notes-pane, .unified-tree-pane, .main-pane, .right-sidebar { border: 1px solid color-mix(in srgb, var(--tigrana-border) 65%, transparent); }
.pane-header { color: var(--tigrana-muted); padding: 16px; font-size: 13px; font-weight: 600; background: var(--surface-soft); border-bottom: 1px solid var(--tigrana-border); }
.topbar { padding: 10px 14px; background: var(--surface-soft); border-bottom: 1px solid var(--tigrana-border); }
.section-view-folder-pane .folder-row { border-radius: 0; margin-right: 6px; }
.note-card, .unified-note-row { border-radius: 9px; }
.title-shell { margin-top: 24px; border-bottom: 0; }
.note-title-input { font-weight: 650; letter-spacing: -0.035em; }
.ProseMirror h1, .ProseMirror h2, .ProseMirror h3 { letter-spacing: -0.025em; font-weight: 650; }
.ProseMirror blockquote { border: 0; border-left: 3px solid var(--tigrana-accent); padding: 12px 18px; background: var(--surface-soft); }
.ProseMirror pre { border: 1px solid var(--tigrana-border); padding: 16px; background: var(--surface-soft); }
.toolbar-button { border-radius: 8px; }

.pane-resizer { background: transparent; }
.pane-resizer::after { opacity: 0; }
.pane-resizer:hover::after, .pane-resizer:focus-visible::after { opacity: 1; }
